def refs():
    return [{**s, "subject": "science", "locator": "熱由高溫傳向低溫、傳導／對流／輻射、熱平衡、保溫、比熱與相變化", "observedPattern": "公開自然科評量常以金屬湯匙、煮水、海陸風、保溫、熱平衡與比熱表格判讀熱流方向和熱傳方式；本題只取能力方向、資料型態與推理層次。", "reuseDecision": "pattern-only", "status": "recorded", "locatorLevel": "paper"} for s in SOURCES]


def make(n, prompt, options, answer, explanation, strategy, steps, difficulty):
    return {"id": f"question-science-content-bb-iv-1-{n}", "subject": "science", "type": "single-choice", "prompt": prompt, "options": [{"id": k, "text": v} for k, v in options.items()], "knowledgeIds": [KG], "difficulty": difficulty, "answer": {"value": answer, "explanation": explanation}, "provenance": {"origin": "original", "license": "All rights reserved", "sourceUrl": SOURCES[0]["url"], "sourceLocator": "三筆公立學校公開自然科資料僅供熱傳方向、熱平衡、傳播方式與比熱推理方向研究；本題未複製原題、選項、圖表或答案。", "authoringNote": "依官方課綱、KG 與三筆公開自然科資料的熱傳能力方向獨立改寫；題幹、選項、答案、解析與五步解法均為原創，待第二輪 AI／Terra 內容複核。"}, "reviewStatus": "draft", "updatedAt": "2026-09-10", "lessonId": LESSON, "examPatternRefs": refs(), "solutionStrategy": strategy, "solutionSteps": steps}


Q = [
    make(1, "90℃金屬棒一端接觸20℃金屬棒，最初熱能的傳遞方向為何？", {"A": "由90℃端傳向20℃端", "B": "由20℃端傳向90℃端", "C": "兩端都沒有熱能傳遞", "D": "熱能只由質量較大端流出"}, "A", "熱會自發由高溫處傳向低溫處，因此最初由90℃端傳向20℃端，選 A。", "先比較溫度，不要用物體含有多少熱量或質量直接判斷熱流方向。", ["列出兩端溫度：90℃與20℃。", "找出高溫端與低溫端。", "熱傳遞的驅動方向是高溫到低溫。", "因此熱能進入20℃的金屬棒。", "所以選 A。"], "easy"),
    make(2, "金屬湯匙放在熱湯中，未浸入湯中的握柄逐漸變熱，主要是哪種熱傳方式？", {"A": "熱傳導", "B": "熱對流", "C": "熱輻射", "D": "化學反應"}, "A", "熱沿著固體金屬由靠近熱湯處傳到握柄，主要是熱傳導，選 A。", "看熱是否沿固體接觸部分逐段傳遞，再與液體流動或電磁波區分。", ["確認湯匙是連續的固體金屬。", "熱湯端先把能量傳給浸入部分。", "能量沿金屬粒子間的接觸傳向握柄。", "過程不以液體整體流動為主。", "所以是熱傳導，選 A。"], "easy"),
    make(3, "鍋中水加熱時，底部較熱的水上升、上部較冷的水下降，這種循環主要是？", {"A": "熱傳導", "B": "熱對流", "C": "熱輻射", "D": "熱平衡停止"}, "B", "液體受熱密度降低而上升，較冷液體下降形成流動，這是熱對流，選 B。", "抓住『流體整體移動』這個熱對流的辨識證據。", ["確認水是可以流動的液體。", "底部水受熱，密度通常減小。", "較熱的水向上移動。", "較冷的水向下補入形成循環。", "所以選 B。"], "easy"),
    make(4, "太陽加熱地球表面時，熱能可穿越接近真空的太空，主要依靠哪種方式？", {"A": "固體傳導", "B": "液體對流", "C": "電磁輻射", "D": "空氣分子碰撞"}, "C", "太空近似真空，缺少傳導與對流所需的物質，但電磁波能傳遞能量，因此主要是熱輻射，選 C。", "先檢查傳熱介質是否存在，再判斷哪種傳熱方式能在真空中進行。", ["確認太陽與地球間大部分路徑近似真空。", "傳導需要粒子接觸，對流需要流體移動。", "電磁波不必依靠物質介質。", "太陽能以輻射形式抵達地球。", "所以選 C。"], "medium"),
    make(5, "熱水與冷水接觸並靜置足夠久後，兩者溫度相同，這表示什麼？", {"A": "已達熱平衡，宏觀上沒有淨熱流", "B": "兩者含有的熱量必定相等", "C": "兩者質量必定相等", "D": "冷水把熱量創造出來"}, "A", "達熱平衡時兩物溫度相同，熱能交換仍可能存在，但沒有從一方到另一方的淨熱流；不能推論熱量相等，選 A。", "精確區分溫度、熱量與熱平衡，避免把三者當成同一物理量。", ["先看接觸前的高低溫差。", "熱由熱水傳向冷水。", "溫差逐漸減小。", "兩者溫度相同時達到熱平衡。", "此時沒有淨熱流，不代表含熱量相等，選 A。"], "medium"),
    make(6, "保溫瓶使用真空夾層與內壁反射表面，主要分別是為了減少哪兩種熱傳？", {"A": "對流與輻射", "B": "傳導與對流", "C": "輻射與化學反應", "D": "蒸發與凝結"}, "A", "真空夾層大幅減少空氣對流，反射表面降低輻射吸收與放出，選 A。", "把每個設計逐一配對到它阻擋的熱傳方式。", ["檢查真空夾層中幾乎沒有氣體流動。", "因此對流受到抑制，也可降低氣體傳導。", "反射表面減少熱輻射的吸收與放出。", "題目問主要配對，選對流與輻射。", "所以選 A。"], "medium"),
    make(7, "冷氣機常安裝在房間較高處，主要利用哪項現象幫助冷空氣分布？", {"A": "冷空氣密度較大會下沉，暖空氣上升形成對流", "B": "冷空氣密度較小會上升", "C": "熱只會由低處傳到高處", "D": "冷氣靠輻射直接穿過牆壁"}, "A", "冷空氣通常較密而下沉，暖空氣上升，形成室內對流循環；高處出風有助於混合，選 A。", "先判斷溫度與密度的關係，再追蹤流體移動方向。", ["冷氣降低周圍空氣溫度。", "同壓下較冷空氣密度通常較大。", "冷空氣下沉，暖空氣上升。", "空氣循環使室內溫度逐漸均勻。", "因此選 A。"], "medium"),
    make(8, "黑色表面通常比光亮表面更容易吸收輻射熱，哪項應用最合理？", {"A": "太陽能熱水器集熱板常使用深色表面", "B": "保溫瓶內壁一定要塗成黑色", "C": "夏天穿黑衣一定比白衣涼", "D": "鏡面越亮越容易吸收所有輻射"}, "A", "深色表面吸收輻射能力通常較強，太陽能集熱板可利用這項特性吸收太陽輻射，選 A。", "將表面顏色與吸收／反射輻射的功能配對，不把吸收和隔熱混為一談。", ["確認太陽能集熱板需要吸收輻射。", "深色表面通常反射較少、吸收較多。", "吸收的輻射轉成集熱板內部熱能。", "這與保溫瓶反射輻射的目的相反。", "所以選 A。"], "easy"),
    make(9, "相同質量的水與金屬吸收相同熱量，水的溫度上升較少，代表水的比熱如何？", {"A": "水的比熱較大", "B": "水的比熱較小", "C": "水沒有比熱", "D": "比熱只由溫度決定"}, "A", "由 Q＝mcΔT，在 Q 與 m 相同時，ΔT 較小表示 c 較大，因此水的比熱較大，選 A。", "固定熱量與質量後，用公式比較溫度變化與比熱的反比關係。", ["確認兩物吸收的熱量 Q 相同。", "確認質量 m 相同。", "水的溫度變化 ΔT 較小。", "由 Q＝mcΔT 可知 c 必須較大。", "所以選 A。"], "medium"),
    make(10, "冰塊放在室溫桌面上會融化，最完整的說法是？", {"A": "周圍溫度較高，熱由周圍傳入冰塊；融化期間吸收潛熱", "B": "冰塊把冷量傳給室內，自己因此融化", "C": "融化一定是放熱過程", "D": "冰塊融化時完全沒有能量轉移"}, "A", "室溫高於冰塊，熱由周圍傳入冰塊；相變需要吸收熔化潛熱，選 A。", "先判斷熱流方向，再區分升溫所需熱量與相變潛熱。", ["比較室溫與冰塊溫度。", "熱由高溫周圍傳向低溫冰塊。", "冰塊吸收能量後晶體結構改變。", "融化階段能量主要用於相變，不必全部表現為升溫。", "所以選 A。"], "medium"),
]

